from typing import List, Union
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from pydantic import BaseModel, validator, ValidationError, root_validator


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Union[str, int, float, Decimal]

    @validator('quantity')
    def quantity_must_be_at_least_1(cls, v):
        if v < 1:
            raise ValueError('quantity must be >= 1')
        return v

    @validator('unit_price', pre=True)
    def unit_price_to_decimal(cls, v):
        try:
            d = Decimal(str(v))
        except Exception:
            raise ValueError('unit_price must be a decimal number')
        if d < 0:
            raise ValueError('unit_price must be >= 0')
        # quantize to 2 decimals for internal consistency
        return d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    def json_dict(self):
        # Return dict with unit_price as string with exactly two decimals
        return {
            'sku': self.sku,
            'quantity': self.quantity,
            'unit_price': f"{self.unit_price:.2f}",
        }


class Invoice(BaseModel):
    number: str
    issued_at: Union[str, datetime]
    lines: List[InvoiceLine]

    @validator('issued_at', pre=True)
    def parse_issued_at(cls, v):
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                # parse ISO8601 string
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError('issued_at must be ISO 8601 datetime string or datetime object')
        else:
            raise ValueError('issued_at must be ISO 8601 datetime string or datetime object')

        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt

    @root_validator
    def check_lines_not_empty(cls, values):
        lines = values.get('lines')
        if not lines or len(lines) == 0:
            raise ValueError('lines must be a non-empty list')
        return values

    def json_dict(self):
        # Format issued_at as "YYYY-MM-DDTHH:MM:SSZ"
        issued_at_str = self.issued_at.strftime('%Y-%m-%dT%H:%M:%SZ')
        lines_out = [line.json_dict() for line in self.lines]
        total = sum(line.quantity * line.unit_price for line in self.lines)
        total_str = f"{total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}"
        return {
            'number': self.number,
            'issued_at': issued_at_str,
            'lines': lines_out,
            'total': total_str,
        }


def export_invoice(data: dict) -> str:
    try:
        invoice = Invoice.parse_obj(data)
    except ValidationError as e:
        # Raise ValueError as requested
        raise ValueError(e)

    import json
    return json.dumps(invoice.json_dict(), separators=(',', ':'))

from typing import List, Optional, Any
from pydantic import BaseModel, validator, ValidationError


class ProfileModel(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @validator('display_name')
    def collapse_whitespace_and_not_blank(cls, v: str) -> str:
        collapsed = ' '.join(v.split())
        if not collapsed:
            raise ValueError('display_name must not be blank')
        return collapsed

    @validator('zip_code', pre=True)
    def ensure_zip_code_str(cls, v: Any) -> str:
        # Accept int or str, convert to str
        return str(v)

    @validator('user_id', pre=True)
    def user_id_numeric_string_to_int(cls, v: Any) -> int:
        # Accept int or numeric string, convert to int
        if isinstance(v, int):
            return v
        if isinstance(v, str) and v.isdigit():
            return int(v)
        raise ValueError('user_id must be an integer or numeric string')


def import_profiles(rows: List[dict]) -> List[dict]:
    valid_profiles = []
    for row in rows:
        try:
            profile = ProfileModel(**row)
            valid_profiles.append(profile.dict())
        except ValidationError:
            # silently skip invalid rows
            continue
    return valid_profiles

from typing import List
from pydantic import BaseModel, ValidationError


class CustomerModel(BaseModel):
    id: int
    name: str
    email: str


class ItemModel(BaseModel):
    sku: str
    quantity: int


class OrderModel(BaseModel):
    id: int
    customer: CustomerModel
    items: List[ItemModel]


def orders_payload(orders: list) -> list:
    """
    Convert ORM order objects into JSON-ready dicts using pydantic models.

    Args:
        orders (list): List of ORM order objects with attributes:
                       - id (int)
                       - customer (object with id, name, email)
                       - items (list of objects with sku, quantity)

    Returns:
        list: List of dicts with keys "id", "customer", and "items" only.

    Raises:
        ValueError: If a required attribute is missing or invalid.
    """
    result = []
    for order in orders:
        try:
            order_dict = {
                "id": getattr(order, "id"),
                "customer": {
                    "id": getattr(order.customer, "id"),
                    "name": getattr(order.customer, "name"),
                    "email": getattr(order.customer, "email"),
                },
                "items": [
                    {
                        "sku": getattr(item, "sku"),
                        "quantity": getattr(item, "quantity"),
                    }
                    for item in getattr(order, "items")
                ],
            }
            validated_order = OrderModel(**order_dict)
            result.append(validated_order.dict())
        except (AttributeError, ValidationError) as e:
            raise ValueError(f"Invalid order data: {e}") from e
    return result

import re
from pydantic import BaseModel, validator, ValidationError


class SignupModel(BaseModel):
    username: str
    email: str
    phone: str
    password: str
    password_confirm: str

    @validator("username")
    def username_valid(cls, v: str) -> str:
        if not re.fullmatch(r"^[a-z0-9_]{3,20}$", v):
            raise ValueError("username must match ^[a-z0-9_]{3,20}$")
        return v

    @validator("email")
    def email_valid(cls, v: str) -> str:
        v = v.strip().lower()
        if "@" not in v:
            raise ValueError("email must contain '@'")
        return v

    @validator("phone")
    def phone_valid(cls, v: str) -> str:
        # Remove spaces, dots, dashes, parentheses
        compact = re.sub(r"[ .\-\(\)]", "", v)
        if not compact.startswith("+"):
            raise ValueError("phone must start with '+'")
        digits = compact[1:]
        if not digits.isdigit():
            raise ValueError("phone must have digits after '+'")
        if not (8 <= len(digits) <= 15):
            raise ValueError("phone digits length must be between 8 and 15")
        return compact

    @validator("password")
    def password_length(cls, v: str) -> str:
        if len(v) < 8:
            raise ValueError("password must be at least 8 characters")
        return v

    @validator("password_confirm")
    def password_confirm_match(cls, v: str, values) -> str:
        pw = values.get("password")
        if pw is not None and v != pw:
            raise ValueError("password_confirm must equal password")
        return v


def validate_signup(data: dict) -> dict:
    validated = SignupModel(**data)
    return {
        "username": validated.username,
        "email": validated.email,
        "phone": validated.phone,
    }

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import List, Union
from pydantic import BaseModel, Field, ValidationError, field_validator


class InvoiceLine(BaseModel):
    sku: str
    quantity: int = Field(..., ge=1)
    unit_price: Decimal = Field(..., ge=0)

    @field_validator('unit_price', mode='before')
    @classmethod
    def validate_unit_price(cls, v):
        # Accept str, int, float; convert to Decimal
        try:
            dec = Decimal(str(v))
        except Exception as e:
            raise ValueError(f"unit_price must be a decimal convertible value: {v}") from e
        if dec < 0:
            raise ValueError("unit_price must be >= 0")
        return dec

    def unit_price_str(self) -> str:
        # Format with exactly two decimals, rounding half up
        return f"{self.unit_price.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)}"


class Invoice(BaseModel):
    number: str
    issued_at: Union[datetime, str]
    lines: List[InvoiceLine]

    model_config = {
        "from_attributes": True,
    }

    @field_validator('issued_at', mode='before')
    @classmethod
    def validate_issued_at(cls, v):
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                # parse ISO 8601 string with fromisoformat (Python 3.11+)
                # fromisoformat does not parse 'Z', so replace it with +00:00
                s = v
                if s.endswith('Z'):
                    s = s[:-1] + '+00:00'
                dt = datetime.fromisoformat(s)
            except Exception as e:
                raise ValueError(f"issued_at must be a valid ISO 8601 datetime string or datetime object: {v}") from e
        else:
            raise ValueError(f"issued_at must be a datetime or ISO 8601 string, got {type(v)}")

        # If naive, assume UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt

    def issued_at_str(self) -> str:
        # Format as "YYYY-MM-DDTHH:MM:SSZ" in UTC
        dt = self.issued_at
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt.strftime('%Y-%m-%dT%H:%M:%SZ')

    def total(self) -> Decimal:
        total = Decimal('0')
        for line in self.lines:
            total += line.unit_price * line.quantity
        return total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)


def export_invoice(data: dict) -> str:
    try:
        invoice = Invoice.model_validate(data)
    except ValidationError as e:
        # Raise ValueError as requested
        raise ValueError(e) from e

    out = {
        "number": invoice.number,
        "issued_at": invoice.issued_at_str(),
        "lines": [
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit_price": line.unit_price_str(),
            }
            for line in invoice.lines
        ],
        "total": f"{invoice.total():.2f}",
    }

    import json
    return json.dumps(out, separators=(',', ':'))

from typing import Any, Optional
from pydantic import BaseModel, Field, ValidationError, field_validator


class Profile(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    model_config = {
        "from_attributes": True,
    }

    @field_validator("display_name")
    @classmethod
    def collapse_whitespace(cls, v: str) -> str:
        # Collapse internal whitespace to single spaces and strip ends
        collapsed = " ".join(v.split())
        if not collapsed:
            raise ValueError("display_name must not be blank")
        return collapsed

    @field_validator("zip_code", mode="before")
    @classmethod
    def ensure_str_zip_code(cls, v: Any) -> str:
        # Accept int or str, always return str
        if isinstance(v, int):
            return str(v)
        if isinstance(v, str):
            return v
        raise TypeError("zip_code must be str or int")


def import_profiles(rows: list) -> list:
    valid_profiles = []
    for row in rows:
        try:
            profile = Profile.model_validate(row)
        except ValidationError:
            continue
        valid_profiles.append(profile.model_dump())
    return valid_profiles

