        "from_attributes": True,
        "extra": "forbid",
    }


def orders_payload(orders: list) -> list:
    try:
        validated_orders = [OrderModel.model_validate(order).model_dump() for order in orders]
    except Exception as e:
        # Pydantic ValidationError is a subclass of ValueError, so we can raise it directly
        raise ValueError(str(e)) from e
    return validated_orders

import re
from pydantic import BaseModel, Field, ValidationError, field_validator


class SignupModel(BaseModel):
    username: str = Field(..., pattern=r'^[a-z0-9_]{3,20}$')
    email: str
    phone: str
    password: str = Field(..., min_length=8)
    password_confirm: str

    model_config = {
        'populate_by_name': True,
    }

    @field_validator('email')
    @classmethod
    def validate_email(cls, v: str) -> str:
        if '@' not in v:
            raise ValueError('email must contain "@"')
        return v.strip().lower()

    @field_validator('phone')
    @classmethod
    def validate_phone(cls, v: str) -> str:
        # Remove spaces, dots, dashes, parentheses
        compact = re.sub(r'[ .\-\(\)]', '', v)
        if not re.fullmatch(r'\+\d{8,15}', compact):
            raise ValueError('phone must be "+" followed by 8-15 digits after removing spaces, dots, dashes, parentheses')
        return compact

    @field_validator('password_confirm')
    @classmethod
    def passwords_match(cls, v: str, info) -> str:
        # info.data contains all fields validated so far
        password = info.data.get('password')
        if password is None:
            # password validation will catch missing password
            return v
        if v != password:
            raise ValueError('password_confirm must equal password')
        return v


def validate_signup(data: dict) -> dict:
    m = SignupModel.model_validate(data)
    return {
        'username': m.username,
        'email': m.email,
        'phone': m.phone,
    }
